class Solution {
public:
    int findTheDistanceValue(vector<int>& arr1, vector<int>& arr2, int d) {
        int ans=0;
        sort(arr2.begin(),arr2.end());
        for(auto it:arr1)
        {
            if(upper_bound(arr2.begin(),arr2.end(),it+d)==lower_bound(arr2.begin(),arr2.end(),it-d))
                ans+=1;
        }
        return ans;
    }
};
